INSERT INTO `event_translations` VALUES (3,2,'fr','Jazz à la Calebasse','Trois nuits de jazz et musiques du monde dans le cadre enchanteur du Jardin de Zaka.','jazz,musique,concert,monde'),(4,2,'en','Jazz at La Calebasse','Three nights of jazz and world music in the enchanting Jardin de Zaka setting.','jazz,music,concert,world'),(5,3,'fr','Salon International de l\'Artisanat','Exposition-vente des meilleurs artisans du Burkina et d\'Afrique de l\'Ouest.','artisanat,shopping,exposition,afrique'),(6,3,'en','International Craft Fair','Exhibition and sale by the finest craftsmen from Burkina and West Africa.','crafts,shopping,exhibition,africa'),(7,4,'fr','Nuit Gastronomique ConnectBé','Soirée dégustation exclusive : cuisine burkinabé revisitée par notre Chef. Sur réservation.','gastronomie,hôtel,dîner,exclusif'),(8,4,'en','ConnectBé Gourmet Evening','Exclusive tasting evening: Burkinabe cuisine revisited by our Chef. By reservation.','gastronomy,hotel,dinner,exclusive'),(9,5,'fr','Marathon International de Ouagadougou','Course populaire ouverte à tous. Distances : 5 km, 10 km, semi et marathon.',NULL),(10,5,'en','Ouagadougou International Marathon','Open race for all. Distances: 5km, 10km, half and full marathon.',NULL),(11,6,'fr','Festival des Masques et des Arts de Dédougou','Célébration des traditions culturelles du Burkina avec masques, danses et musiques.',NULL),(12,6,'en','Dédougou Masks and Arts Festival','Celebration of Burkina\'s cultural traditions with masks, dances and music.',NULL),(13,7,'fr','Exposition Photo — Regards sur le Burkina','50 photographes africains posent leur regard sur le quotidien burkinabé. Entrée libre.','photo,exposition,art,gratuit'),(14,7,'en','Photo Exhibition — Views on Burkina','50 African photographers document everyday Burkinabe life. Free entry.','photo,exhibition,art,free'),(15,8,'fr','Soirée Live au Rooftop','Concert acoustique en plein air sur la terrasse de l\'hôtel. Entrée libre pour les résidents.','musique,hôtel,rooftop,live'),(16,8,'en','Live Rooftop Evening','Open-air acoustic concert on the hotel terrace. Free entry for hotel guests.','music,hotel,rooftop,live'),(19,6,'de','Festival der Masken und Künste von Dédougou','Feier der kulturellen Traditionen Burkinas mit Masken, Tänzen und Musik.',NULL),(20,6,'es','Festival de Máscaras y Artes de Dédougou','Celebración de las tradiciones culturales de Burkina con máscaras, bailes y música.',NULL),(21,6,'pt','Festival de Máscaras e Artes de Dédougou','Celebração das tradições culturais do Burkina Faso com máscaras, danças e música.',NULL),(22,6,'ar','مهرجان ديدوغو للأقنعة والفنون','الاحتفال بالتقاليد الثقافية لبوركينا فاسو بالأقنعة والرقصات والموسيقى.',NULL),(23,6,'zh','代杜古面具和艺术节','用面具、舞蹈和音乐庆祝布基纳法的文化传统。',NULL),(24,6,'ja','Dédougou仮面と芸術の祭典','マスク、ダンス、音楽でブルキナファソの文化的伝統を祝いましょう。',NULL),(25,6,'ru','Фестиваль масок и искусств в Дедугу','Празднование культурных традиций Буркина-Фасо с помощью масок, танцев и музыки.',NULL),(26,9,'fr','Semaine nationale de la culture de Bobo Dioulasso','Placée sous le thème « Culture, jeunesse et transmission des valeurs sociales », la 22ᵉ édition de la Semaine nationale de la culture (SNC) se tiendra du 25 avril au 2 mai 2026 à Bobo-Dioulasso.  Au-delà de la célébration de cette édition, le Burkina Faso aura également l’honneur d’abriter la 2ᵉ édition de la Semaine de la fraternité de la confédération des États du Sahel.',NULL),(27,9,'en','Bobo Dioulasso National Culture Week','Under the theme \"Culture, youth and the transmission of social values\", the 22nd edition of National Week of Culture (SNC) will be held from 25 April to 2 May 2026 in Bobo-Dioulasso. Beyond the celebration of this edition, Burkina Faso will also have the honour to host the 2nd edition of the Fraternity Week of the Confederation of Sahel States.',NULL),(28,9,'de','Nationale Bobo Dioulasso Kulturwoche','Unter dem Motto „Kultur, Jugend und Vermittlung sozialer Werte“ findet die 22. Ausgabe der Nationalen Kulturwoche (NSW) vom 25. April bis 2. Mai 2026 in Bobo-Dioulasso statt.  Neben der Feier dieser Ausgabe wird Burkina Faso auch die Ehre haben, die 2. Ausgabe der Woche der Brüderlichkeit der Konföderation der Sahel-Staaten auszurichten.',NULL),(29,9,'es','Semana Nacional de la Cultura de Bobo Dioulasso','Bajo el lema “Cultura, juventud y transmisión de valores sociales”, la 22ª edición de la Semana Nacional de la Cultura (SNC) se celebrará del 25 de abril al 2 de mayo de 2026 en Bobo-Dioulasso.  Más allá de la celebración de esta edición, Burkina Faso también tendrá el honor de albergar la 2ª edición de la Semana de la Fraternidad de la Confederación de Estados del Sahel.',NULL),(30,9,'pt','Semana Nacional da Cultura de Bobo Dioulasso','Colocada sob o tema “Cultura, juventude e transmissão de valores sociais”, a 22ª edição da Semana Nacional da Cultura (San) será realizada de 25 de abril a 2 de maio de 2026 em Bobo-Dioulasso.  Além da celebração desta edição, Burkina Faso também terá a honra de sediar a 2ª edição da Semana da Fraternidade da Confederação dos Estados do Sahel.',NULL),(31,9,'ar','أسبوع بوبو ديولاسو الوطني للثقافة','وفي إطار موضوع \" الثقافة والشباب ونقل القيم الاجتماعية \" ، ستعقد الطبعة 22 من الأسبوع الوطني للثقافة في الفترة من 25 نيسان/أبريل إلى 2 أيار/مايو 2026 في بوبو - ديولاسو. وإلى جانب الاحتفال بهذه الطبعة، ستتشرف بوركينا فاسو أيضا باستضافة الطبعة الثانية من أسبوع الأخوة في اتحاد دول الساحل.',NULL),(32,9,'zh','Bobo Dioulasso国家文化周','第22届全国文化周（ SNC ）将以“文化、青年和社会价值观的传播”为主题，于2026年4月25日至5月2日在博博迪乌拉索举行。除了庆祝这一周，布基纳法索还将荣幸地主办第二届萨赫勒国家联邦博爱周。',NULL),(33,9,'ja','ボボ・ディウラッソ・ナショナル・カルチャー・ウィーク','「文化、若者、社会的価値の伝達」をテーマに、第22回全国文化週間（ SNC ）が2026年4月25日から5月2日までボボ・ディウラッソで開催されます。このエディションのお祝いを超えて、ブルキナファソはまた、サヘル諸国連盟の第2回友愛週間を主催する栄誉を得ています。',NULL),(34,9,'ru','Национальная неделя культуры в Бобо-Диулассо','С 25 апреля по 2 мая 2026 года в Бобо-Диулассо пройдет 22-я Национальная неделя культуры (SNC), посвященная теме «Культура, молодежь и передача социальных ценностей».  Помимо празднования этого события, Буркина-Фасо также будет иметь честь принять 2-е издание Недели братства Конфедерации государств Сахеля.',NULL),(44,10,'fr','Événement Test',NULL,NULL),(45,11,'fr','Soirée Hôtel',NULL,NULL),(47,11,'en','Hotel Evening',NULL,NULL),(48,11,'de','Hotel Abend',NULL,NULL),(49,11,'es','Hotel Evening',NULL,NULL),(50,11,'pt','Noite do Hotel',NULL,NULL),(51,11,'ar','Hotel Evening',NULL,NULL),(52,11,'zh','酒店晚报',NULL,NULL),(53,11,'ja','ホテル イブニング',NULL,NULL),(54,11,'ru','Вечер в отеле',NULL,NULL),(102,12,'fr','Salon International du Tourisme et de l\'hôtellerie de Ouagadougou (SITHO, 16e édition)','Salon International du Tourisme et de l\'hôtellerie de Ouagadougou — 16e édition.',NULL),(103,13,'fr','Atelier national sur le renouveau culturel du Burkina','Atelier national sur le renouveau culturel du Burkina dans le contexte de la Révolution Progressiste Populaire.',NULL),(104,14,'fr','Universités Africaines de la Communication de Ouagadougou (UACO, 29e édition)','Universités Africaines de la Communication de Ouagadougou — 29e édition.',NULL),(105,15,'fr','Colloque international sur l’héritage de Cheick Anta DIOP','Colloque international « Souveraineté : héritage culturel et vision de Cheick Anta DIOP ».',NULL),(106,16,'fr','Célébration du 39e anniversaire de l’assassinat du Camarade Président Thomas SANKARA','Célébration du 39e anniversaire de l’assassinat du Camarade Président Thomas SANKARA et de ses douze compagnons.',NULL),(107,17,'fr','Tournée des Orchestres de la Révolution','Tournée des Orchestres de la Révolution (Petits Chanteurs aux Poings Levés + Colombes de la Révolution) — Dano, Dissin, Gaoua.',NULL),(108,18,'fr','Nuit du Communicateur (Zama d\'Or, 1re édition)','Nuit du Communicateur — Zama d\'Or, 1re édition.',NULL),(109,19,'fr','Prix National de l\'Entrepreneur Touristique (PNET, 8e édition)','Prix National de l\'Entrepreneur Touristique — 8e édition.',NULL),(110,20,'fr','Les Rencontres des Arts du Musée National du Burkina Faso (RENCARTS)','Les Rencontres des Arts du Musée National du Burkina Faso.',NULL),(111,21,'fr','Tournée des Ensembles Artistiques Nationaux','Tournée des Ensembles Artistiques Nationaux — Ziniaré, Kaya.',NULL),(112,22,'fr','Symposium international de sculptures sur granite de Laongo (Sympo granit, 15e édition)','Symposium international de sculptures sur granite de Laongo — 15e édition.',NULL),(113,23,'fr','Colloque scientifique « La sculpture sur granite »','Colloque scientifique « La sculpture sur granite : expression et construction des identités culturelles ».',NULL),(114,24,'fr','Marathon Houet des Éditions Sidwaya','Marathon Houet des Éditions Sidwaya.',NULL),(115,25,'fr','Vernissage de l’exposition « Les Trésors du Liptako »','Vernissage de l’exposition « Les Trésors du Liptako ».',NULL),(116,26,'fr','Rentrée du Droit d\'Auteur (RDA, 8e édition) et 40 ans du BBDA','Rentrée du Droit d\'Auteur (RDA, 8e édition) et Commémoration des 40 ans du Bureau Burkinabè du Droit d\'Auteur (BBDA).',NULL),(117,27,'fr','Nuit des partenaires du MCCAT','Nuit des partenaires du Ministère de la Communication, de la Culture, des Arts et du Tourisme.',NULL),(121,12,'en','International Tourism and Hospitality Exhibition in Ouagadougou (SITHO, 16th edition)','International Tourism and Hospitality Exhibition in Ouagadougou — 16th edition.',NULL),(122,12,'de','Internationale Ausstellung für Tourismus und Hospitality in Ouagadougou (SITHO, 16. Auflage)','Internationale Messe für Tourismus und Hotellerie in Ouagadougou — 16. Ausgabe.',NULL),(123,12,'es','Exposición Internacional de Turismo y Hospitalidad en Uagadugú (SITHO, 16a edición)','Exposición Internacional de Turismo y Hospitalidad en Uagadugú — 16a edición.',NULL),(124,12,'pt','Exposição Internacional de Turismo e Hospitalidade em Ouagadougou (SITHO, 16a edição)','Exposição Internacional de Turismo e Hotelaria de Ouagadougou — 16ª edição.',NULL),(125,12,'ar','International Tourism and Hospitality Exhibition in Ouagadougou (SITHO, 16th edition)','المعرض الدولي للسياحة والضيافة في واغادوغو — الطبعة السادسة عشرة.',NULL),(126,12,'zh','瓦加杜古国际旅游和招待展览会(SITHO,第16版)','瓦加杜古国际旅游和酒店展览会—第16届。',NULL),(127,12,'ja','Ouagadougouの国際観光とホスピタリティ展(SITHO、16版)','ワガドゥグの国際観光とホスピタリティ展—第16版。',NULL),(128,12,'ru','Международная выставка туризма и гостеприимства в Уагадугу (SITHO, 16-е издание)','Международная выставка туризма и гостеприимства в Уагадугу — 16-е издание.',NULL),(129,28,'fr','Salon International de l\'Artisanat de Ouagadougou (SIAO)','Thème : « Artisanat africain et industrialisation : quelle synergie pour une meilleure organisation et valorisation des produits locaux et du patrimoine culturel ». Tarif d\'entrée non encore communiqué.',NULL);
