INSERT INTO `hotel_tips` VALUES (1,1,2,'Horaires piscine','Pool hours','Ouverte de 7h à 21h','Open from 7am to 9pm','Équipements',0,1,0,'2026-04-10 00:35:39','2026-04-15 13:20:31','{\"de\":{\"titre\":\"Öffnungszeiten Schwimmbad\",\"contenu\":\"Geöffnet von 7 bis 21 Uhr\"},\"es\":{\"titre\":\"Horarios piscina\",\"contenu\":\"Abierto de 7:00 a 21:00\"},\"pt\":{\"titre\":\"Horas de piscina\",\"contenu\":\"Aberto das 7h às 21h\"},\"ar\":{\"titre\":\"ساعات خدمة UberPool\",\"contenu\":\"يفتح من الساعة 00/7 إلى الساعة 00/9\"},\"zh\":{\"titre\":\"优步拼车时段\",\"contenu\":\"开放时间: 7: 00至9: 00\"},\"ja\":{\"titre\":\"UberPoolの利用時間\",\"contenu\":\"営業時間:午前7時から午後9時まで\"},\"ru\":{\"titre\":\"Часы работы бассейна\",\"contenu\":\"Открыто с 7:00 до 21:00\"}}'),(2,2,6,'Happy Hours','Happy Hours','TOut les soirs de 19h à 21h','TOUT in the evenings from 7pm to 9pm','Offre',1,1,0,'2026-04-15 15:55:23','2026-04-15 15:56:52','{\"de\":{\"titre\":\"Happy Hours\",\"contenu\":\"Jeden Abend von 19:00 bis 21:00 Uhr\"},\"es\":{\"titre\":\"Happy Hours\",\"contenu\":\"Todas las noches de 19:00 a 21:00\"},\"pt\":{\"titre\":\"Happy Hours\",\"contenu\":\"TOUT à noite das 19h às 21h\"},\"ar\":{\"titre\":\"الساعات السعيدة\",\"contenu\":\"TOUT في المساء من 7 مساءً إلى 9 مساءً\"},\"zh\":{\"titre\":\"活动 \",\"contenu\":\"晚上7点至9点TOUT\"},\"ja\":{\"titre\":\"ハッピーアワー\",\"contenu\":\"午後7時から午後9時までの夜間のTOUT\"},\"ru\":{\"titre\":\"Счастливые часы\",\"contenu\":\"TOUT по вечерам с 19:00 до 21:00\"}}'),(3,2,7,'Canicule ! ','Hot!','Canicule, songez à vous hydrater correctement.','Heat, think about hydrating yourself properly.',NULL,0,1,1,'2026-05-04 19:50:58','2026-05-04 19:51:32','{\"de\":{\"titre\":\"Heiß!\",\"contenu\":\"Heat, denken Sie daran, sich richtig zu hydratisieren.\"},\"es\":{\"titre\":\"¡Caliente!\",\"contenu\":\"Calor, piensa en hidratarte adecuadamente.\"},\"pt\":{\"titre\":\"Quente!\",\"contenu\":\"Onda de calor, pense em hidratar-se adequadamente.\"},\"ar\":{\"titre\":\"حار!\",\"contenu\":\"موجة الحر، فكر في ترطيب نفسك بشكل صحيح.\"},\"zh\":{\"titre\":\"烫!\",\"contenu\":\"热浪，想想适当地给自己补水。\"},\"ja\":{\"titre\":\"ホット!\",\"contenu\":\"ヒートウェーブ、適切に水分補給することを考えてください。\"},\"ru\":{\"titre\":\"Шарав\",\"contenu\":\"Тепловая волна, подумайте о правильном увлажнении.\"}}'),(4,1,1,'SITHO 2026','SITHO 2026','Bienvenue au SITHO 2026','Welcome to SITHO 2026','Sympa',1,1,0,'2026-09-18 01:03:44','2026-09-18 01:47:52','{\"de\":{\"titre\":\"SITHO 2026\",\"contenu\":\"Willkommen bei SITHO 2026\"},\"es\":{\"titre\":\"SITHO 2026\",\"contenu\":\"Bienvenido a SITHO 2026\"},\"pt\":{\"titre\":\"SITO 2026\",\"contenu\":\"Bem-vindo ao SITHO 2026\"},\"ar\":{\"titre\":\"SITHO 2026\",\"contenu\":\"مرحبًا بكم في SITHO 2026\"},\"zh\":{\"titre\":\"SITHO 2026\",\"contenu\":\"欢迎来到SITHO 2026\"},\"ja\":{\"titre\":\"SITHO 2026\",\"contenu\":\"SITHO 2026へようこそ\"},\"ru\":{\"titre\":\"SITHO 2026\",\"contenu\":\"\"}}');
